var styles_default2 = "/*\n * Task-board styles. Every selector is hand-scoped under `.dsh-tasks` (this\n * file is embedded verbatim \u2014 no build-time scoping), and uses DSH design\n * tokens (`--dsw-*`) so light/dark themes follow automatically.\n */\n\n.dsh-tasks {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  min-height: 0;\n  padding: 12px 16px;\n  box-sizing: border-box;\n  font-family: var(--dsw-font-family, inherit);\n  color: var(--dsw-alias-label-primary);\n}\n\n/* \u2500\u2500 header \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.dsh-tasks .tk-head {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex: none;\n  margin-bottom: 12px;\n}\n\n.dsh-tasks .tk-modes {\n  display: inline-flex;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.dsh-tasks .tk-mode {\n  border: none;\n  background: transparent;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  line-height: 18px;\n  padding: 5px 14px;\n  cursor: pointer;\n}\n\n.dsh-tasks .tk-mode-on {\n  background: var(--dsw-alias-state-business-primary);\n  color: #fff;\n}\n\n.dsh-tasks .tk-archived-toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 12px;\n  color: var(--dsw-alias-label-secondary);\n  cursor: pointer;\n}\n\n.dsh-tasks .tk-actions {\n  margin-left: auto;\n  display: inline-flex;\n  gap: 8px;\n}\n\n.dsh-tasks .tk-btn {\n  border: 1px solid var(--dsw-alias-border-l2);\n  background: transparent;\n  color: var(--dsw-alias-label-primary);\n  font-size: 12px;\n  line-height: 18px;\n  padding: 5px 12px;\n  border-radius: 8px;\n  cursor: pointer;\n}\n\n.dsh-tasks .tk-btn:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n\n.dsh-tasks .tk-btn:disabled {\n  opacity: 0.45;\n  cursor: default;\n}\n\n.dsh-tasks .tk-btn-primary {\n  background: var(--dsw-alias-state-business-primary);\n  border-color: var(--dsw-alias-state-business-primary);\n  color: #fff;\n}\n\n.dsh-tasks .tk-btn-primary:hover {\n  background: var(--dsw-alias-state-business-primary);\n  opacity: 0.9;\n}\n\n.dsh-tasks .tk-btn-danger {\n  border-color: var(--dsw-alias-state-error-primary);\n  color: var(--dsw-alias-state-error-primary);\n}\n\n.dsh-tasks .tk-link-btn {\n  border: none;\n  background: transparent;\n  color: var(--dsw-alias-state-business-primary);\n  font-size: 12px;\n  cursor: pointer;\n  padding: 2px 4px;\n}\n\n.dsh-tasks .tk-error {\n  flex: none;\n  margin: 0 0 10px;\n  font-size: 12px;\n  color: var(--dsw-alias-state-error-primary);\n}\n\n.dsh-tasks .tk-notice {\n  flex: none;\n  margin: 0 0 10px;\n  font-size: 12px;\n  color: var(--dsw-alias-state-success-primary, #2e9e5b);\n}\n\n/* \u2500\u2500 board \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.dsh-tasks .tk-board {\n  flex: 1;\n  min-height: 0;\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 10px;\n}\n\n.dsh-tasks .tk-col {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 10px;\n  background: var(--dsw-alias-bg-layer-3);\n}\n\n.dsh-tasks .tk-col-head {\n  flex: none;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 8px 12px;\n  font-size: 12px;\n  font-weight: 600;\n  border-bottom: 1px solid var(--dsw-alias-border-l2);\n}\n\n.dsh-tasks .tk-count {\n  font-size: 11px;\n  color: var(--dsw-alias-label-secondary);\n  background: var(--dsw-alias-interactive-bg-hover);\n  border-radius: 9px;\n  padding: 0 8px;\n  line-height: 18px;\n}\n\n.dsh-tasks .tk-col-body {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding: 8px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.dsh-tasks .tk-card {\n  flex: none;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-2);\n  padding: 8px 10px;\n  cursor: pointer;\n  box-shadow: var(--dsw-shadow-lv1, none);\n}\n\n.dsh-tasks .tk-card:hover {\n  border-color: var(--dsw-alias-state-business-primary);\n}\n\n.dsh-tasks .tk-card-title {\n  font-size: 13px;\n  line-height: 18px;\n  overflow-wrap: anywhere;\n  margin-bottom: 6px;\n}\n\n.dsh-tasks .tk-card-meta {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.dsh-tasks .tk-prio {\n  font-size: 10px;\n  line-height: 16px;\n  padding: 0 6px;\n  border-radius: 8px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dsh-tasks .tk-prio-high {\n  border-color: var(--dsw-alias-state-error-primary);\n  color: var(--dsw-alias-state-error-primary);\n}\n\n.dsh-tasks .tk-prio-low {\n  border-color: var(--dsw-alias-state-business-primary);\n  color: var(--dsw-alias-state-business-primary);\n}\n\n.dsh-tasks .tk-due {\n  font-size: 10px;\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dsh-tasks .tk-due-over {\n  color: var(--dsw-alias-state-error-primary);\n  font-weight: 600;\n}\n\n.dsh-tasks .tk-col-empty {\n  margin: 0;\n  text-align: center;\n  font-size: 12px;\n  color: var(--dsw-alias-label-tertiary);\n}\n\n/* \u2500\u2500 list \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.dsh-tasks .tk-list-wrap {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 10px;\n  background: var(--dsw-alias-bg-layer-3);\n}\n\n.dsh-tasks .tk-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 12px;\n}\n\n.dsh-tasks .tk-table th {\n  text-align: left;\n  font-weight: 600;\n  color: var(--dsw-alias-label-secondary);\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--dsw-alias-border-l2);\n  position: sticky;\n  top: 0;\n  background: var(--dsw-alias-bg-layer-3);\n}\n\n.dsh-tasks .tk-table td {\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--dsw-alias-border-l2);\n}\n\n.dsh-tasks .tk-table tbody tr {\n  cursor: pointer;\n}\n\n.dsh-tasks .tk-table tbody tr:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n\n.dsh-tasks .tk-row-archived {\n  opacity: 0.55;\n}\n\n.dsh-tasks .tk-cell-title {\n  font-weight: 600;\n}\n\n.dsh-tasks .tk-cell-muted {\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dsh-tasks .tk-foot {\n  flex: none;\n  margin: 8px 0 0;\n  font-size: 11px;\n  color: var(--dsw-alias-label-tertiary);\n}\n\n/* \u2500\u2500 editor modal \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.dsh-tasks .tk-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 1100;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 24px;\n}\n\n.dsh-tasks .tk-mask {\n  position: absolute;\n  inset: 0;\n  background: var(--dsw-alias-bg-mask-1);\n  backdrop-filter: var(--dsw-mask-blur);\n}\n\n.dsh-tasks .tk-dialog {\n  position: relative;\n  z-index: 1;\n  box-sizing: border-box;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  width: min(560px, 100%);\n  max-height: 80vh;\n  overflow: auto;\n  padding: 16px 18px;\n  border: 1px solid var(--dsw-alias-border-inverted);\n  border-radius: 16px;\n  background: var(--dsw-alias-bg-layer-2);\n  box-shadow: var(--dsw-shadow-lv3);\n}\n\n.dsh-tasks .tk-dialog-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n}\n\n.dsh-tasks .tk-dialog-title {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 20px;\n}\n\n.dsh-tasks .tk-close {\n  border: 0;\n  background: transparent;\n  cursor: pointer;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 14px;\n  line-height: 1;\n  padding: 2px;\n}\n\n.dsh-tasks .tk-field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  font-size: 12px;\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dsh-tasks .tk-field-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr 1.4fr;\n  gap: 10px;\n}\n\n.dsh-tasks .tk-input,\n.dsh-tasks .tk-textarea {\n  box-sizing: border-box;\n  width: 100%;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  background: transparent;\n  color: var(--dsw-alias-label-primary);\n  font-size: 12px;\n  font-family: var(--dsw-font-family, inherit);\n}\n\n.dsh-tasks .tk-input {\n  height: 30px;\n  padding: 0 10px;\n}\n\n.dsh-tasks .tk-textarea {\n  padding: 8px 10px;\n  resize: vertical;\n  line-height: 18px;\n}\n\n.dsh-tasks .tk-dialog-foot {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  margin-top: 2px;\n}\n\n.dsh-tasks .tk-foot-left,\n.dsh-tasks .tk-foot-right {\n  display: inline-flex;\n  gap: 8px;\n}\n\n/* \u2500\u2500 settings section \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n.dsh-tasks .tk-settings {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  max-width: 640px;\n}\n\n.dsh-tasks .tk-settings-head h2 {\n  margin: 0 0 6px;\n  font-size: 15px;\n  font-weight: 600;\n}\n\n.dsh-tasks .tk-settings-head p {\n  margin: 0;\n  font-size: 12px;\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dsh-tasks .tk-settings-meta {\n  margin: 0;\n  font-size: 12px;\n  color: var(--dsw-alias-label-secondary);\n}\n";

